export function businessKind(name){if(/^(?:Pottery Barn|Voluspa|U\.?S\.? Polo)/i.test(name))return /Pottery/i.test(name)?'home':/Voluspa/i.test(name)?'beauty':'apparel';if(/World of Hearing|Totally Chi Reflexology/i.test(name))return 'service';if (/^(?:CHAGEE|HEYTEA|Nespresso|See.s Candies|Sugarfina|Läderach)/i.test(name))return 'food';if (/^(?:Brioni|Alo Yoga|Beyond Yoga|Beauty Creations)/i.test(name))return /Beauty Creations/i.test(name)?'beauty':'apparel';for(const [kind,re] of Object.entries(categories))if(re.test(name))return kind;return 'apparel';}

const colors=['#789384','#a78369','#748d9a','#a58a9e','#998d67'];
const hash=s=>[...s].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,7);
export const isServiceStore=st=>['service','visitor','entertainment','auto','gallery'].includes(st?.businessKind);
const jointFamilies={aerieamericaneagleoutfitters:['aerie','americaneagle'],auntieannescinnabon:['auntieannes','cinnabon'],auntieannespretzelscinnabon:['auntieannes','cinnabon'],wetzelscoldstone:['wetzelspretzels','coldstonecreamery'],wetzelspretzelscoldstonecreamery:['wetzelspretzels','coldstonecreamery'],calzedoniaintimissimi:['calzedonia','intimissimi']};
const rawKey=name=>String(name).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');
const ruleIndex=new Map();
for(const rule of RETAILER_BRAND_EVIDENCE)for(const name of rule.merchants){const k=merchantIdentity(name);if(!ruleIndex.has(k))ruleIndex.set(k,[]);ruleIndex.get(k).push(rule);}
function audienceMatches(st,p){return storeAudience(st.name)!=='child'||p.audience==='child'||/\b(?:kids|kid|child|children|toddler|baby|boys|girls|youth)\b/i.test(p.name);}
function conditionMatches(p,r){if(!r.condition)return true;const c=String(r.condition).toLowerCase();return !/pre.?owned|used/i.test(c)||/pre.?owned|used/i.test(p.condition||'');}
const ownFeedHosts={calpak:['calpaktravel.com'],industrieaustralia:['industrie.com.au'],nati:['natiboutique.com'],collegium:['ourcollegium.com'],stjohn:['stjohnknits.com'],beachbunny:['beachbunnyswimwear.com'],emiliageorge:['emiliageorgeofficial.com'],rookiekids:['rookieusa.com']};
function normalizeSeed(p){const host=new URL(p.source).hostname.replace(/^www\./,''),maker={'calpaktravel.com':'CALPAK','industrie.com.au':'Industrie','ourcollegium.com':'Collegium','stjohnknits.com':'St. John','beachbunnyswimwear.com':'Beach Bunny'}[host];const q={...p,...maker?{brand:maker}:{}};if(/americangirl\.com/.test(host))q.type='toy';if(/\b(?:youth|pre.?school|big kid|little kid|toddler|baby|kids|children|boys|girls)\b/i.test(q.name)||['shoes','sandals'].includes(q.type)&&/\b(?:TD|PS|GS|crib)\b/.test(q.name))q.audience='child';return q;}
export function associationFor(st,p){
 if(!audienceMatches(st,p))return null;
 const maker=merchantIdentity(p.brand),family=merchantIdentity(st.name),joint=jointFamilies[rawKey(st.name)]||[];
 if((maker===family||joint.includes(maker))&&!/pre.?owned|used/i.test(p.condition||''))return {kind:'own-brand',merchant:st.name,brand:p.brand,source:p.source,checkedOn:p.referenceCheckedOn||p.checkedOn||'2026-10-27'};
 const host=new URL(p.source).hostname.replace(/^www\./,'');if(p.seed&&merchantIdentity(p.merchant||'')===family&&ownFeedHosts[family]?.includes(host))return {kind:'retailer-product',merchant:st.name,brand:p.brand,source:p.source,checkedOn:p.checkedOn||'2026-10-27'};
 const names=p.merchantNames||[p.merchant||p.retailer||''],e=p.merchantEvidence||{};
 if(names.some(n=>merchantIdentity(n)===family)&&/own-retailer|official-merchant-product|exact-retailer-product/.test(e.kind||'')&&p.seed)return {kind:'retailer-product',merchant:st.name,brand:p.brand,source:p.source,checkedOn:p.referenceCheckedOn||p.checkedOn||'2026-10-27'};
 // A same-merchant legacy public product feed is evidence for a sub-label sold by that merchant.
 if(p.seed&&merchantIdentity(p.merchant||'')===family&&p.sourceKind!=='retailer-product-page'&&p.priceBasis?.startsWith('Official')&&merchantIdentity(new URL(p.source).hostname.replace(/^www\./,'').split('.')[0])===family&&!isDepartmentMerchant(st.name))return {kind:'merchant-product',merchant:st.name,brand:p.brand,source:p.source,checkedOn:p.checkedOn||'2026-10-27'};
 for(const r of ruleIndex.get(family)||[]){if(!r.allowedBrands.some(b=>merchantIdentity(b)===maker)||r.allowedProductTypes.length&&!r.allowedProductTypes.includes(p.type)||!conditionMatches(p,r))continue;return {kind:'documented-carried-brand',merchant:st.name,brand:p.brand,source:r.source,checkedOn:r.checkedOn,historical:r.historical,note:r.note};}
 return null;
}
function diversified(candidates,limit){const groups=new Map();for(const q of candidates){const k=merchantIdentity(q.p.brand);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(q);}const result=[];for(let i=0;result.length<limit;i++){let any=false;for(const values of groups.values())if(values[i]){result.push(values[i]);any=true;if(result.length===limit)break;}if(!any)break;}return result;}
export function installPlayableStores(stores,products,photos){
 const core=stores.slice(),base=products.splice(0),seeds=STORE_PRODUCT_SEEDS.map(normalizeSeed).map((p,i)=>({...p,id:p.id||'real-seed-'+i,price:Math.round(p.priceUSD*100),retail:Math.round(p.priceUSD*100),sizes:p.sizes?.length?p.sizes:['One size'],color:p.color||'#9f9989',material:p.material||'Real named product. Game fit and stock are simulated.',assetKey:p.id||'real-seed-'+i,seed:true}));
 for(const p of seeds)if(p.photo)photos[p.id]=p.photo;
 for(const p of base){const photo=photos[p.id];if(photo?.source?.startsWith('https://')&&photo.source!==p.source){if(/\.pdf(?:$|[?#])/.test(p.source)&&p.observedPriceDate&&!p.priceSource)p.priceSource=p.source;p.source=photo.source;p.sourceKind='product';}}
 const all=[...base,...seeds],brandIndex=new Map(),merchantIndex=new Map();
 for(const p of all){const maker=merchantIdentity(p.brand);if(!brandIndex.has(maker))brandIndex.set(maker,[]);brandIndex.get(maker).push(p);if(p.seed)for(const n of p.merchantNames||[p.merchant||p.retailer||'']){const key=merchantIdentity(n);if(!merchantIndex.has(key))merchantIndex.set(key,[]);merchantIndex.get(key).push(p);}}

 // Every active listing requires a brand or retailer evidence path, including the original story shops.
 for(const st of core){st.businessKind=businessKind(st.name);st.branch=false;st.assortmentBasis='verified-brand-reference';}
 for(const [mallId,source]of Object.entries(CENTER_DIRECTORIES)){const mall=MALLS.find(m=>m.id===mallId),tier=MALLS.indexOf(mall),coreByKey=new Map(core.filter(st=>mall.sections.some(d=>d.stores.includes(st.id))).map(st=>{const t=matchingTenant(mallId,st.id,core);return t&&gameStoreFloor(mall,st.id,core)===tenantFloor(mallId,t)?[t.key,st]:[null,null];}));for(const t of source.tenants){if(coreByKey.get(t.key))continue;const id=mallId+'-tenant-'+(t.key||normalizeName(t.name)),kind=businessKind(t.name),section=mall.sections[hash(id)%mall.sections.length],st={id,name:t.name,tier,district:section.id,mallId,floor:tenantFloor(mallId,t),tenantKey:t.key,branch:true,businessKind:kind,color:colors[hash(id)%colors.length],light:'#eee7d8',npc:['Alex','Riley','Morgan','Jamie','Taylor'][hash(id)%5],sub:'REAL PRODUCT COLLECTION',policy:30,source:t.url||t.source||source.source};stores.push(st);if(!section.stores.includes(id))section.stores.push(id);}}
 for(const st of stores){
  if(isServiceStore(st)){st.catalogStatus='service';st.sub='SERVICES & EXPERIENCES';st.greeting='Come inside, meet the team and choose a service or activity. All payments use game money.';continue;}
  const identities=new Set(),family=merchantIdentity(st.name),families=new Set([family,...jointFamilies[rawKey(st.name)]||[]]);for(const r of ruleIndex.get(family)||[])for(const name of r.allowedBrands)families.add(merchantIdentity(name));
  const original=base.filter(p=>p.store===st.id),pool=[...new Set([...original,...merchantIndex.get(family)||[],...[...families].flatMap(k=>brandIndex.get(k)||[])])],ordered=[...original,...pool.filter(p=>p.seed),...pool.filter(p=>!p.seed&&p.store!==st.id)],candidates=[];
  for(const p of ordered){if(!photos[p.id]||!Number.isSafeInteger(p.price)||p.price<=0)continue;const evidence=associationFor(st,p);if(!evidence)continue;const identity=merchantIdentity(p.brand)+'|'+p.name.toLowerCase();if(identities.has(identity))continue;identities.add(identity);candidates.push({p,evidence});}
  candidates.sort((a,b)=>(a.p.audience==='child')-(b.p.audience==='child'));
  const selected=diversified(candidates,isDepartmentMerchant(st.name)?60:48);
  if(selected.some(({p})=>p.id.startsWith('v37-real-')))st.collectionEdition=37;
  if(selected.some(({p})=>p.id.startsWith('v38-book-')))st.collectionEdition=38;
  for(const {p,evidence}of selected){const pid=p.store===st.id?p.id:st.id+'::'+p.id,q={...p,id:pid,store:st.id,modelId:p.modelId||p.id,finalSale:p.finalSale||['food','drink'].includes(p.type),assortmentBasis:evidence.kind==='own-brand'?'brand-models':'documented-retailer',associationEvidence:evidence,observedPriceDate:p.referencePriceVerified?p.referenceCheckedOn:p.observedPriceDate||(/official|published/i.test(p.priceBasis||'')&&!/simulated reference|cached/i.test(p.priceBasis||'')?p.checkedOn:undefined)};if(p.store!==st.id){const factor={ross:.4,marshalls:.65,nordstromrack:.6,saksoff5th:.55}[merchantIdentity(st.name)];if(factor){q.price=Math.max(100,Math.round(p.price*factor));q.gamePriceBasis='Original off-price game discount applied to the model reference, not a real store quote.';}}delete q.photo;products.push(q);photos[pid]=photos[p.id];}
  st.catalogStatus=selected.length?'verified':'pending';st.assortmentBasis='verified-brand-reference';st.sub=selected.length?'REAL PRODUCT COLLECTION':'CATALOG RESEARCH IN PROGRESS';st.greeting=selected.length?'Browse this store’s real products and documented carried brands. Every label links to its source. Game prices, stock, fit and return policies are simulated.':'Welcome inside. This store’s verified photographed catalog is still being researched. Earlier purchases can still be returned here under their original game terms.';
 }
 return {core,seeds};
}
